2	index df474ece..50e7cdd7 100644
3	--- a/reverie-kvm/src/elf.rs
4	+++ b/reverie-kvm/src/elf.rs
5	@@ -6,16 +6,20 @@
6	  * LICENSE file in the root directory of this source tree.
7	  */
8	 
9	+use std::ffi::CStr;
10	 use std::fs::File;
11	 use std::fs::OpenOptions;
12	 use std::io::Read;
13	 use std::os::fd::AsRawFd;
14	+use std::os::fd::FromRawFd;
15	+use std::os::fd::RawFd;
16	 use std::os::unix::ffi::OsStrExt;
17	 use std::os::unix::fs::FileExt;
18	 use std::os::unix::fs::OpenOptionsExt;
19	 use std::path::Path;
20	 use std::path::PathBuf;
21	 use std::sync::Arc;
22	+use std::sync::OnceLock;
23	 use std::sync::atomic::AtomicU8;
24	 use std::sync::atomic::Ordering;
25	 
26	@@ -61,6 +65,115 @@ pub(crate) const GUEST_CAPABILITY_MASK: u64 = (1_u64 << 41) - 1;
27	 /// relocated interpreter base. Only applies when the main image would overrun
28	 /// the historical fixed [`INTERPRETER_LOAD_BIAS`]; small PIEs are unaffected.
29	 const INTERPRETER_MIN_BRK_HEADROOM: u64 = 4 * 1024 * 1024;
30	+const PROC_SUPER_MAGIC: libc::c_long = 0x9fa0;
31	+const POLICY_OPEN_EINTR_ATTEMPTS: usize = 16;
32	+
33	+/// Host behavior around Linux commit 43b450632676fb60e9faeddff285d9fac94a4f58,
34	+/// which moved invalid O_CREAT|O_DIRECTORY admission ahead of path lookup.
35	+#[derive(Clone, Copy, Debug, Eq, PartialEq)]
36	+pub(crate) enum RegularCreateDirectoryPolicy {
37	+    EarlyEinval,
38	+    LegacyLookup,
39	+}
40	+
41	+static REGULAR_CREATE_DIRECTORY_POLICY: OnceLock<
42	+    std::result::Result<RegularCreateDirectoryPolicy, String>,
43	+> = OnceLock::new();
44	+
45	+fn raw_openat_with_bounded_eintr(
46	+    path: &CStr,
47	+    flags: libc::c_int,
48	+) -> std::result::Result<RawFd, libc::c_int> {
49	+    for _ in 0..POLICY_OPEN_EINTR_ATTEMPTS {
50	+        // SAFETY: path is NUL-terminated and live for the call. A zero mode is
51	+        // valid, and the verified existing path cannot be created by the probe.
52	+        let result =
53	+            unsafe { libc::syscall(libc::SYS_openat, libc::AT_FDCWD, path.as_ptr(), flags, 0) };
54	+        if result >= 0 {
55	+            return Ok(result as RawFd);
56	+        }
57	+        let errno = std::io::Error::last_os_error()
58	+            .raw_os_error()
59	+            .unwrap_or(libc::EIO);
60	+        if errno != libc::EINTR {
61	+            return Err(errno);
62	+        }
63	+    }
64	+    Err(libc::EINTR)
65	+}
66	+
67	+fn probe_regular_create_directory_policy()
68	+-> std::result::Result<RegularCreateDirectoryPolicy, String> {
69	+    let path = c"/proc/self/status";
70	+    let verification_fd = raw_openat_with_bounded_eintr(path, libc::O_PATH | libc::O_CLOEXEC)
71	+        .map_err(|errno| format!("cannot verify /proc/self/status: errno {errno}"))?;
72	+    // SAFETY: the raw open returned a new owned descriptor.
73	+    let verification = unsafe { File::from_raw_fd(verification_fd) };
74	+    let mut metadata = std::mem::MaybeUninit::<libc::stat>::zeroed();
75	+    // SAFETY: metadata is writable and verification remains live.
76	+    if unsafe { libc::fstat(verification.as_raw_fd(), metadata.as_mut_ptr()) } != 0 {
77	+        return Err(format!(
78	+            "cannot stat /proc/self/status: errno {}",
79	+            std::io::Error::last_os_error()
80	+                .raw_os_error()
81	+                .unwrap_or(libc::EIO)
82	+        ));
83	+    }
84	+    // SAFETY: fstat initialized metadata on success.
85	+    let metadata = unsafe { metadata.assume_init() };
86	+    if metadata.st_mode & libc::S_IFMT != libc::S_IFREG {
87	+        return Err(format!(
88	+            "/proc/self/status is not regular: mode {:#o}",
89	+            metadata.st_mode
90	+        ));
91	+    }
92	+    let mut filesystem = std::mem::MaybeUninit::<libc::statfs>::zeroed();
93	+    // SAFETY: filesystem is writable and verification remains live.
94	+    if unsafe { libc::fstatfs(verification.as_raw_fd(), filesystem.as_mut_ptr()) } != 0 {
95	+        return Err(format!(
96	+            "cannot statfs /proc/self/status: errno {}",
97	+            std::io::Error::last_os_error()
98	+                .raw_os_error()
99	+                .unwrap_or(libc::EIO)
100	+        ));
101	+    }
102	+    // SAFETY: fstatfs initialized filesystem on success.
103	+    let filesystem = unsafe { filesystem.assume_init() };
104	+    if filesystem.f_type as libc::c_long != PROC_SUPER_MAGIC {
105	+        return Err(format!(
106	+            "/proc/self/status is not on procfs: f_type {:#x}",
107	+            filesystem.f_type
108	+        ));
109	+    }
110	+    drop(verification);
111	+
112	+    let flags = libc::O_RDONLY | libc::O_CREAT | libc::O_DIRECTORY | libc::O_CLOEXEC;
113	+    match raw_openat_with_bounded_eintr(path, flags) {
114	+        Err(libc::EINVAL) => Ok(RegularCreateDirectoryPolicy::EarlyEinval),
115	+        Err(libc::ENOTDIR) => Ok(RegularCreateDirectoryPolicy::LegacyLookup),
116	+        Err(errno) => Err(format!(
117	+            "unsupported O_CREAT|O_DIRECTORY result for /proc/self/status: errno {errno}"
118	+        )),
119	+        Ok(fd) => {
120	+            // SAFETY: the policy probe unexpectedly returned a new descriptor;
121	+            // close it before failing initialization.
122	+            let close_result = unsafe { libc::close(fd) };
123	+            Err(format!(
124	+                "O_CREAT|O_DIRECTORY unexpectedly opened /proc/self/status (close={close_result})"
125	+            ))
126	+        }
127	+    }
128	+}
129	+
130	+pub(crate) fn initialize_regular_create_directory_policy() -> Result<RegularCreateDirectoryPolicy> {
131	+    match REGULAR_CREATE_DIRECTORY_POLICY.get_or_init(probe_regular_create_directory_policy) {
132	+        Ok(policy) => Ok(*policy),
133	+        Err(error) => Err(Error::HostIo(std::io::Error::new(
134	+            std::io::ErrorKind::Unsupported,
135	+            format!("cannot establish O_CREAT|O_DIRECTORY host policy: {error}"),
136	+        ))),
137	+    }
138	+}
139	 
140	 const AT_NULL: u64 = 0;
141	 const AT_PHDR: u64 = 3;
142	@@ -734,6 +847,13 @@ pub(crate) struct LoadedStaticElf {
143	     // this side table only marks which fds must report stable, synthesized
144	     // metadata instead of the memfd's per-run inode.
145	     pub proc_files: std::collections::BTreeMap<i32, u64>,
146	+    /// Synthetic proc descriptions opened with O_NOFOLLOW. The private carrier
