fn pread64(memory: &mut GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    let Ok(fd) = i32::try_from(args[0]) else {
        return negative_errno(libc::EBADF);
    };
    if let Some(description) = state.fdinfo_files.get(&fd).cloned() {
        return description.read(memory, args, true);
    }
    let Ok(requested_length) = usize::try_from(args[2]) else {
        return negative_errno(libc::EINVAL);
    };
    let length = requested_length.min(MAX_HOST_IO);
    let Some(file) = state.files.get(&fd) else {
        return negative_errno(libc::EBADF);
    };
    if let Err(error) = ensure_readable(file) {
        return error;
    }
    if length == 0 {
        return 0;
    }
    if !range_is_valid(memory, args[1], length as u64) {
        return negative_errno(libc::EFAULT);
    }
    let Ok(writable) = memory.user().user_accessible_prefix(args[1], length) else {
        return negative_errno(libc::EFAULT);
    };
    if writable == 0 {
        return negative_errno(libc::EFAULT);
    }
    let mut bytes = vec![0; writable];
    match file.read_at(&mut bytes, args[3]) {
        Ok(count) => match memory.user().write(args[1], &bytes[..count]) {
            Ok(()) => count as i64,
            Err(_) => negative_errno(libc::EFAULT),
        },
        Err(error) => io_error(error),
    }
}

fn pwrite64(memory: &GuestMemory, state: &LoadedStaticElf, args: &[u64; 6]) -> i64 {
    if (args[3] as libc::off_t) < 0 {
        return negative_errno(libc::EINVAL);
    }
    // Linux syscall argument decoding consumes only the low descriptor word.
    let fd = args[0] as libc::c_int;
    let Ok(requested_length) = usize::try_from(args[2]) else {
        return negative_errno(libc::EINVAL);
    };
    let length = requested_length.min(MAX_HOST_IO);
    let Some(file) = state.files.get(&fd) else {
        return negative_errno(libc::EBADF);
    };
    if let Some(&inode) = state
        .proc_files
        .get(&fd)
        .filter(|inode| !is_synthetic_proc_directory_inode(**inode))
    {
        // Regular procfs files do not support positioned writes. After the
        // global signed-offset check, O_PATH access precedes the path-specific
        // procfs refusal.
        return match file_status_flags(file) {
            Ok(status) if status & libc::O_PATH != 0 => negative_errno(libc::EBADF),
            Ok(_) => negative_errno(synthetic_proc_pwrite_errno(inode)),
            Err(error) => error,
        };
    }
    if let Err(error) = ensure_writable(file) {
        return error;
    }
    if length == 0 {
        return 0;
    }
    let mut bytes = vec![0; length];
    if memory.user().read(args[1], &mut bytes).is_err() {
        return negative_errno(libc::EFAULT);
    }
    file.write_at(&bytes, args[3])
        .map_or_else(io_error, |count| count as i64)
}

