+    EXPECT_ERROR(open("/proc/uptime", O_RDWR | O_TMPFILE, 0600), ENOTDIR);
+    EXPECT_ERROR(open("/proc/uptime", O_ACCMODE | O_TMPFILE, 0600), ENOTDIR);
+    EXPECT_ERROR(open("/proc/uptime", O_PATH | O_TMPFILE, 0600), ENOTDIR);
